      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A fonte orienta verificar no riser flexível a existência de torção, vazamentos, estanqueidade da capa externa por teste de injeção de nitrogênio quando necessário, ruptura de fitas, desalinhamento ou sobreposição de arames e arames rompidos.",
          "trechos": [
            "E3e87d7c7ff675b6a:0:692"
          ],
          "condicoes": [
            "no contexto de inspeção do riser flexível",
            "teste de nitrogênio apenas quando necessário, conforme o próprio trecho"
          ],
          "limites": [
            "o trecho lista itens de verificação, mas não fornece método detalhado, critérios de aceitação nem pressão de teste",
            "não vincula explicitamente essas verificações a uma etapa específica de pull-in"
          ]
        },
        {
          "proposicao": "A fonte recomenda inspecionar no conector a integridade de conectores, revestimento, corrosão, parafusos de fixação, válvulas de alívio de gás permeado, sistema de fixação do riser ao hang-off e parafusos de fechamento da traseira.",
          "trechos": [
            "E3e87d7c7ff675b6a:692:1385"
          ],
          "condicoes": [
            "na inspeção de conectores e interface com hang-off"
          ],
          "limites": [
            "não há priorização de criticidade entre os itens nem critérios quantitativos",
            "o trecho não descreve compatibilidade com um modelo específico de FPSO ou conector"
          ]
        },
        {
          "proposicao": "A fonte inclui como itens de verificação a integridade da interface entre spool rígido e conector de topo, a integridade do sistema de monitoramento do espaço anular e, no bending stiffener, trincas, abrasão, deformações e fixação.",
          "trechos": [
            "E3e87d7c7ff675b6a:1385:2072"
          ],
          "condicoes": [
            "quando existirem spool rígido, conector de topo, sistema de monitoramento do espaço anular e bending stiffener no arranjo inspecionado"
          ],
          "limites": [
            "trata-se de checklist de inspeção e não de análise causal de falha",
            "o trecho não informa como esses achados afetam a decisão de continuar, suspender ou abandonar a operação"
          ]
        }
      ]
    },
    {
