        },
        {
          "proposicao": "A fonte explica que a vídeoscopia industrial com boroscópio é usada para avaliar a integridade de trechos emersos de risers flexíveis no interior de I-tubes, podendo exigir abertura de janelas para permitir acesso de inspeção.",
          "trechos": [
            "E3825c52aab48a089:1397:2092",
            "E3825c52aab48a089:2092:2188"
          ],
          "condicoes": [
            "para risers flexíveis em operação ou desativados no interior de I-tubes",
            "quando o acesso exigir abertura de janelas na UEP"
          ],
          "limites": [
            "a fonte descreve finalidade e recursos, sem informar resolução, cobertura ou limitações de detecção",
            "não estabelece que a técnica substitua outras inspeções ou testes de estanqueidade"
          ]
        }
      ]
    },
