      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte explica que, após o lançamento do riser rígido, é necessária a transferência do topo da embarcação de lançamento para a unidade flutuante por meio de ferramenta no topo do riser e cabos de aço interligando riser, embarcação de lançamento e unidade flutuante.",
          "trechos": [
            "Ecb60aa1f4112a5ee:0:693"
          ],
          "condicoes": [
            "após lançamento do riser rígido por método como Reel-Lay ou J-Lay",
            "quando houver conexão posterior à unidade flutuante"
          ],
          "limites": [
            "não descreve dimensionamento nem integridade dos cabos de aço",
            "o trecho não aborda falha de cabo ou guincho, apenas seu uso na transferência"
          ]
        },
        {
          "proposicao": "A operação de pull-in é descrita como suspensão do riser com seu conector até ultrapassar o receptáculo, seguida de descida para assentamento do conector, que passa a sustentar toda a carga do SCR.",
          "trechos": [
            "Ecb60aa1f4112a5ee:693:1391"
          ],
          "condicoes": [
            "na conexão do SCR à unidade flutuante após a transferência do topo"
          ],
          "limites": [
